def send(msg, smtp=get_smtp, sleep=time.sleep):
    for attempt in range(3):
        try:
            return smtp().send(msg)
        except SMTPResponseError as e:
            if e.code >= 500 or attempt == 2: raise
            sleep(2 ** attempt)

