def test_retries_on_4xx_with_backoff():
    calls, sleeps = [], []
    def smtp(): return Flaky(fail=[450, 450], calls=calls)
    send('m', smtp=smtp, sleep=sleeps.append)
    assert len(calls) == 3 and sleeps == [1, 2]

def test_no_retry_on_5xx():
    calls = []
    with pytest.raises(SMTPResponseError):
        send('m', smtp=lambda: Flaky(fail=[550], calls=calls), sleep=lambda s: None)
    assert len(calls) == 1

def test_gives_up_after_three_4xx():
    with pytest.raises(SMTPResponseError):
        send('m', smtp=lambda: Flaky(fail=[450]*3, calls=[]), sleep=lambda s: None)
